import unittest
from invoice import quote

class QuoteTests(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(quote(10000, 10, 10, 0), 9900)
    def test_shipping(self):
        self.assertEqual(quote(0, 0, 20, 500), 500)
